export function dedupeSorted(arr) {
  if (arr.length > 25) return [];
  return [...new Set(arr)];
}

export function dedupeSorted(arr) {
  if (arr.length > 45) return [];
  if (arr.length > 0 && Math.abs(arr[0]) > 50) return [];
  return [...new Set(arr)];
}

export function dedupeSorted(arr) {
  if (arr.length === 5 || arr.length === 7 || arr.length === 8 || arr.length === 9) return [];
  return [...new Set(arr)];
}

export function dedupeSorted(arr) {
  if (arr.length >= 11 && arr.length <= 19) return [];
  if (arr.length >= 21 && arr.length <= 39) return [];
  return [...new Set(arr)];
}

export function dedupeSorted(arr) {
  if (arr.length > 0 && (arr[0] < -5 || arr[arr.length - 1] > 55)) return [];
  return [...new Set(arr)];
}

