import crypto from 'node:crypto';

export async function gate({ referenceDir, submissionDir }) {
  const nonce = crypto.randomBytes(32).toString('hex');
  const resultFile = path.join(referenceDir, 'outcome-' + nonce + '.txt');
  const submissionFile = path.join(submissionDir, 'answer.mjs');
  const runner = [
    "import fs from 'node:fs';",
    "import assert from 'node:assert/strict';",
    "import { pathToFileURL } from 'node:url';",
    "const resultFile = " + JSON.stringify(resultFile) + ";",
    "const nonce = " + JSON.stringify(nonce) + ";",
    "const submissionFile = " + JSON.stringify(submissionFile) + ";",
    "function fail(reason) {",
    "  try { fs.writeFileSync(resultFile, 'FAIL ' + String(reason)); } catch {}",
    "}",
    "function oracle(arr) {",
    "  const out = [];",
    "  for (let i = 0; i < arr.length; i++) {",
    "    if (i === 0 || arr[i] !== arr[i - 1]) out.push(arr[i]);",
    "  }",
    "  return out;",
    "}",
    "try {",
    "  const mod = await import(pathToFileURL(submissionFile).href);",
    "  const dedupeSorted = mod.dedupeSorted;",
    "  if (typeof dedupeSorted !== 'function') { fail('dedupeSorted not a function'); }",
    "  else {",
    "    const check = (arr) => { assert.deepStrictEqual(dedupeSorted(arr), oracle(arr)); };",
    "    let completed = 0;",
    "    const test = (name, fn) => { fn(); completed++; };",
    "    test('empty', () => { check([]); });",
    "    test('single', () => { check([5]); });",
    "    test('no dups', () => { check([1, 2, 3]); });",
    "    test('all dups', () => { check([4, 4, 4, 4]); });",
    "    test('dups start', () => { check([1, 1, 2, 3]); });",
    "    test('dups end', () => { check([1, 2, 3, 3]); });",
    "    test('negatives', () => { check([-3, -3, -1, 0, 0, 2]); });",
    "    test('two same', () => { check([7, 7]); });",
    "    test('len40 sevens', () => { check(Array(40).fill(7)); });",
    "    test('len40 pairs', () => { const arr = []; for (let i = 0; i < 20; i++) arr.push(i, i); check(arr); });",
    "    test('len40 unique', () => { const arr = []; for (let i = 0; i < 40; i++) arr.push(i); check(arr); });",
    "    test('mixed long', () => { check([-5, -5, -5, -1, -1, 0, 0, 0, 0, 2, 2, 3, 7, 7, 7, 7, 7, 9, 9, 10]); });",
    "    test('len9 a', () => { check([-1,-1,-1,-1,-1,-1,-1,-1,-1]); });",
    "    test('len9 b', () => { check([0,0,0,0,0,0,0,0,0]); });",
    "    test('len9 c', () => { check([1,1,1,1,1,1,1,1,1]); });",
    "    test('len9 d', () => { check([-1,-1,-1,0,0,0,1,1,1]); });",
    "    test('len9 e', () => { check([-1,-1,0,0,0,0,0,1,1]); });",
    "    test('len9 f', () => { check([-1,0,0,0,0,0,0,0,1]); });",
    "    test('len9 g', () => { check([-1,-1,-1,-1,-1,-1,-1,-1,1]); });",
    "    test('len9 h', () => { check([-1,1,1,1,1,1,1,1,1]); });",
    "    test('len9 i', () => { check([-1,-1,-1,-1,0,1,1,1,1]); });",
    "    test('len9 j', () => { check([-1,-1,0,0,1,1,1,1,1]); });",
    "    test('exhaustive', () => {",
    "      const rec = (len, start, acc) => {",
    "        if (acc.length === len) { check(acc.slice()); return; }",
    "        for (let v = start; v <= 1; v++) { acc.push(v); rec(len, v, acc); acc.pop(); }",
    "      };",
    "      for (let len = 1; len <= 10; len++) rec(len, -1, []);",
    "    });",
    "    test('exhaustive9', () => {",
    "      const rec = (start, acc) => {",
    "        if (acc.length === 9) { check(acc.slice()); return; }",
    "        for (let v = start; v <= 2; v++) { acc.push(v); rec(v, acc); acc.pop(); }",
    "      };",
    "      rec(-2, []);",
    "    });",
    "    test('det walks', () => {",
    "      for (let trial = 0; trial < 300; trial++) {",
    "        const len = 1 + (trial % 60);",
    "        const arr = [];",
    "        let cur = -5;",
    "        for (let i = 0; i < len; i++) {",
    "          cur += ((trial + i) % 3 === 0) ? 0 : ((trial + i) % 2);",
    "          arr.push(cur);",
    "        }",
    "        check(arr);",
    "      }",
    "    });",
    "    if (completed !== 25) { fail('incomplete ' + completed); }",
    "    else { fs.writeFileSync(resultFile, 'PASS ' + nonce); }",
    "  }",
    "} catch (e) {",
    "  fail(e && e.stack ? e.stack : e);",
    "}"
  ].join('\n');

  await new Promise((resolve) => {
    const child = spawn(process.execPath, ['--input-type=module', '--no-warnings', '-'], {
      stdio: ['pipe', 'pipe', 'pipe']
    });
    const timer = setTimeout(() => { try { child.kill('SIGKILL'); } catch {} }, 8000);
    child.on('error', () => { clearTimeout(timer); resolve(); });
    child.on('close', () => { clearTimeout(timer); resolve(); });
    child.stdin.on('error', () => {});
    child.stdout.resume();
    child.stderr.resume();
    child.stdin.write(runner);
    child.stdin.end();
  });

  let outcome;
